    @Test
    void variableRiseMatchesRateScenarioForBothRepaymentMethods() {
        for (RepaymentMethod method : RepaymentMethod.values()) {
            var type = calc("30000000", 35, method, "0.5", 5, "1.0", 10, "1.0", "0.5", "2.0").cases().get(1);
            var scenario = RateRiseCalculator.compare(new BigDecimal("30000000"), new BigDecimal("0.5"),
                    35, method, 5, List.of(new BigDecimal("1.0"))).scenarios().get(0);
            assertThat(type.monthlyPaymentBeforeSwitch()).isEqualByComparingTo(scenario.monthlyPaymentBefore());
            assertThat(type.monthlyPaymentAfterSwitch()).isEqualByComparingTo(scenario.monthlyPaymentAfter());
            assertThat(type.totalPayment()).isEqualByComparingTo(scenario.totalPayment());
            assertThat(type.totalInterest()).isEqualByComparingTo(scenario.totalInterest());
            for (int year = 0; year < 35; year++) {
                BigDecimal total = scenario.monthlyPayments().subList(year * 12, (year + 1) * 12)
                        .stream().reduce(BigDecimal.ZERO, BigDecimal::add);
                assertThat(type.yearlyPayments().get(year)).isEqualByComparingTo(total);
            }
        }
    }

    @Test
    void variableFlat_equalsPlainRepaymentCalculator() {
        BigDecimal principal = new BigDecimal("30000000");
        RateTypeComparison r = calc("30000000", 35, RepaymentMethod.EQUAL_PAYMENT,
                "0.5", 5, "1.0", 10, "1.0", "0.5", "2.0");
        BigDecimal plain = RepaymentCalculator.calculate(principal, new BigDecimal("0.5"), 35,
                RepaymentMethod.EQUAL_PAYMENT, BigDecimal.ZERO).totalPayment();

        assertThat(r.cases().get(0).totalPayment()).isEqualByComparingTo(plain);
        assertThat(r.cases().get(0).totalPayment()).isEqualByComparingTo("32707747");
    }

    @Test
    void variableRise_equalsFixedPeriod_whenYearsAndRatesMatch() {
        // Same switch year and same first/after rates -> the two two-stage models are identical.
        RateTypeComparison r = calc("30000000", 35, RepaymentMethod.EQUAL_PAYMENT,
                "1.0", 7, "0.5", 7, "1.0", "1.5", "2.0");

        RateTypeComparison.Case rise = r.cases().get(1);
        RateTypeComparison.Case fixed = r.cases().get(2);
        assertThat(rise.rateAfterPercent()).isEqualByComparingTo(fixed.rateAfterPercent());
        assertThat(rise.switchAfterYears()).isEqualTo(fixed.switchAfterYears());
        assertThat(rise.firstMonthlyPayment()).isEqualTo(fixed.firstMonthlyPayment());
        assertThat(rise.monthlyPaymentBeforeSwitch()).isEqualTo(fixed.monthlyPaymentBeforeSwitch());
        assertThat(rise.monthlyPaymentAfterSwitch()).isEqualTo(fixed.monthlyPaymentAfterSwitch());
        assertThat(rise.totalPayment()).isEqualTo(fixed.totalPayment());
        assertThat(rise.yearlyPayments()).isEqualTo(fixed.yearlyPayments());
    }

